# Identify major phases using 200-day moving average crossover
df['MA200'] = df['Close'].rolling(200).mean()
# Shade bear markets (price below 200-day MA from peak)
bear_mask = df['Close'] < df['MA200'] * 0.9  # 10% below MA
bear_groups = (bear_mask != bear_mask.shift()).cumsum()
for _, group in df[bear_mask].groupby(bear_groups):
    if len(group) > 20:  # Only mark sustained periods
        ax.axvspan(group['Date'].iloc[0], group['Date'].iloc[-1], alpha=0.12, color=ACCENT)

ax.set_ylabel('Closing Price (USD)')
ax.set_title('AXP Long-Term Price Trend — Bear Phases Highlighted (Red Shading)', fontweight='bold')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}'))
