# ── Drawdown Episodes ─────────────────────────────────────────────────────
def find_drawdown_episodes(df, threshold=-15):
    """Find major drawdown episodes exceeding threshold."""
    episodes = []
    in_dd = False
    start_idx = None
    for i in range(1, len(df)):
        if df['Drawdown'].iloc[i] < threshold / 100 and not in_dd:
            in_dd = True
            start_idx = i
        elif df['Drawdown'].iloc[i] >= -0.02 and in_dd:
            trough_idx = df.loc[start_idx:i, 'Drawdown'].idxmin()
            peak_idx = df.loc[:trough_idx, 'Close'].idxmax()
            episodes.append({
                'peak_date': df['Date'].iloc[peak_idx],
                'trough_date': df['Date'].iloc[trough_idx],
                'recovery_date': df['Date'].iloc[i],
                'drawdown': df['Drawdown'].iloc[trough_idx] * 100,
                'peak_price': df['Close'].iloc[peak_idx],
                'trough_price': df['Close'].iloc[trough_idx],
            })
            in_dd = False
    # If still in drawdown at end
    if in_dd:
        trough_idx = df.loc[start_idx:, 'Drawdown'].idxmin()
        peak_idx = df.loc[:trough_idx, 'Close'].idxmax()
        episodes.append({
            'peak_date': df['Date'].iloc[peak_idx],
            'trough_date': df['Date'].iloc[trough_idx],
            'recovery_date': None,
            'drawdown': df['Drawdown'].iloc[trough_idx] * 100,
            'peak_price': df['Close'].iloc[peak_idx],
            'trough_price': df['Close'].iloc[trough_idx],
        })
    episodes.sort(key=lambda x: x['drawdown'])
    return episodes[:8]

