#!/usr/bin/env python3
"""Generate AXP Historical Stock Performance Report as self-contained HTML."""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
from io import BytesIO
import base64
import os

# ── Configuration ──────────────────────────────────────────────────────────
PRIMARY = '#006FCF'   # Amex blue
DARK    = '#1a1a2e'
ACCENT  = '#e63946'
GREEN   = '#2d6a4f'
GOLD    = '#c9a227'
GRAY    = '#6b7280'
LIGHT   = '#f8f9fa'
DARK_BG = '#0d1b2a'

plt.rcParams.update({
    'figure.facecolor': 'white',
    'axes.facecolor':   'white',
    'axes.edgecolor':   '#cccccc',
    'axes.grid':        True,
    'grid.color':       '#e5e7eb',
    'grid.alpha':       0.7,
    'font.family':      'sans-serif',
    'font.size':        11,
    'axes.titlesize':   14,
    'axes.labelsize':   12,
})

# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)
df['Year']  = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

# ── KPI Calculations ───────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close  = df['Close'].iloc[-1]
first_date  = df['Date'].iloc[0]
last_date   = df['Date'].iloc[-1]
years_span  = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years_span) - 1) * 100

# Daily returns & volatility
df['DailyReturn'] = df['Close'].pct_change()
# Exclude early years with zero volume (unreliable returns) for volatility calc
df_vol = df[df['Volume'] > 0].copy()
daily_vol = df_vol['DailyReturn'].std()
annualized_vol = daily_vol * np.sqrt(252) * 100

# Max drawdown
df['CumMax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['CumMax']) / df['CumMax']
max_dd_idx = df['Drawdown'].idxmin()
max_dd = df['Drawdown'].iloc[max_dd_idx] * 100
max_dd_date = df['Date'].iloc[max_dd_idx]
max_dd_peak_idx = df.loc[:max_dd_idx, 'Close'].idxmax()
max_dd_peak_date = df['Date'].iloc[max_dd_peak_idx]

# Total dividends
total_dividends = df['Dividends'].sum()

# All-time high / low
ath_idx = df['Close'].idxmax()
atl_idx = df['Close'].idxmin()
ath_price = df['Close'].iloc[ath_idx]
ath_date  = df['Date'].iloc[ath_idx]
atl_price = df['Close'].iloc[atl_idx]
atl_date  = df['Date'].iloc[atl_idx]

# ── Drawdown Episodes ─────────────────────────────────────────────────────
def find_drawdown_episodes(df, threshold=-15):
    """Find major drawdown episodes exceeding threshold."""
    episodes = []
    in_dd = False
    start_idx = None
    for i in range(1, len(df)):
        if df['Drawdown'].iloc[i] < threshold / 100 and not in_dd:
            in_dd = True
            start_idx = i
        elif df['Drawdown'].iloc[i] >= -0.02 and in_dd:
            trough_idx = df.loc[start_idx:i, 'Drawdown'].idxmin()
            peak_idx = df.loc[:trough_idx, 'Close'].idxmax()
            episodes.append({
                'peak_date': df['Date'].iloc[peak_idx],
                'trough_date': df['Date'].iloc[trough_idx],
                'recovery_date': df['Date'].iloc[i],
                'drawdown': df['Drawdown'].iloc[trough_idx] * 100,
                'peak_price': df['Close'].iloc[peak_idx],
                'trough_price': df['Close'].iloc[trough_idx],
            })
            in_dd = False
    # If still in drawdown at end
    if in_dd:
        trough_idx = df.loc[start_idx:, 'Drawdown'].idxmin()
        peak_idx = df.loc[:trough_idx, 'Close'].idxmax()
        episodes.append({
            'peak_date': df['Date'].iloc[peak_idx],
            'trough_date': df['Date'].iloc[trough_idx],
            'recovery_date': None,
            'drawdown': df['Drawdown'].iloc[trough_idx] * 100,
            'peak_price': df['Close'].iloc[peak_idx],
            'trough_price': df['Close'].iloc[trough_idx],
        })
    episodes.sort(key=lambda x: x['drawdown'])
    return episodes[:8]

dd_episodes = find_drawdown_episodes(df, threshold=-20)

# ── Decade-by-Decade Analysis ─────────────────────────────────────────────
decades = []
for decade_start in [1970, 1980, 1990, 2000, 2010, 2020]:
    ddf = df[df['Decade'] == decade_start]
    if len(ddf) == 0:
        continue
    d_first = ddf['Close'].iloc[0]
    d_last  = ddf['Close'].iloc[-1]
    d_ret   = (d_last / d_first - 1) * 100
    d_years = (ddf['Date'].iloc[-1] - ddf['Date'].iloc[0]).days / 365.25
    d_cagr  = ((d_last / d_first) ** (1 / max(d_years, 0.01)) - 1) * 100 if d_years > 0 else 0
    d_vol_ddf = ddf[ddf['Volume'] > 0]
    d_vol = d_vol_ddf['DailyReturn'].std() * np.sqrt(252) * 100 if len(d_vol_ddf) > 1 else 0
    d_max_dd = ddf['Drawdown'].min() * 100
    d_div = ddf['Dividends'].sum()
    d_avg_vol = d_vol_ddf['Volume'].mean() if len(d_vol_ddf) > 0 else 0
    decades.append({
        'decade': f"{decade_start}s",
        'start_price': d_first,
        'end_price': d_last,
        'return_pct': d_ret,
        'cagr': d_cagr,
        'volatility': d_vol,
        'max_drawdown': d_max_dd,
        'total_dividends': d_div,
        'avg_daily_volume': d_avg_vol,
    })

# ── Sub-period CAGR ───────────────────────────────────────────────────────
sub_periods = [
    ("1972–1982", "1972-01-01", "1982-12-31"),
    ("1982–1992", "1982-01-01", "1992-12-31"),
    ("1992–2002", "1992-01-01", "2002-12-31"),
    ("2002–2012", "2002-01-01", "2012-12-31"),
    ("2012–2022", "2012-01-01", "2022-12-31"),
    ("Full Period", str(first_date.date()), str(last_date.date())),
]
sub_cagrs = []
for label, s, e in sub_periods:
    sdf = df[(df['Date'] >= pd.Timestamp(s, tz='UTC')) & (df['Date'] <= pd.Timestamp(e, tz='UTC'))]
    if len(sdf) < 2:
        continue
    sp = sdf['Close'].iloc[0]
    ep = sdf['Close'].iloc[-1]
    yrs = (sdf['Date'].iloc[-1] - sdf['Date'].iloc[0]).days / 365.25
    c = ((ep / sp) ** (1 / max(yrs, 0.01)) - 1) * 100 if yrs > 0 else 0
    sub_cagrs.append({'period': label, 'cagr': c, 'start': sp, 'end': ep, 'years': yrs})

# ── Dividend history by year ──────────────────────────────────────────────
df_div = df[df['Dividends'] > 0].copy()
div_by_year = df_div.groupby('Year')['Dividends'].sum().reset_index()
div_by_year.columns = ['Year', 'TotalDividends']

# Stock splits
splits = df[df['Stock Splits'] > 0][['Date', 'Stock Splits']].copy()
splits['Date'] = splits['Date'].dt.strftime('%Y-%m-%d')

# ── Chart Generation Helpers ──────────────────────────────────────────────
def fig_to_base64(fig, dpi=150):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64

# ── Chart 1: Long-Term Price Trend ────────────────────────────────────────
fig, ax = plt.subplots(figsize=(14, 6))
ax.semilogy(df['Date'], df['Close'], color=PRIMARY, linewidth=0.8, alpha=0.9)
ax.set_ylabel('Closing Price (USD, log scale)')
ax.set_title('American Express (AXP) — Closing Price 1972–2026 (Log Scale)', fontweight='bold')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}' if x >= 1 else f'${x:.2f}'))
ax.annotate(f'All-Time High: ${ath_price:,.2f}\n({ath_date.strftime("%b %Y")})',
            xy=(ath_date, ath_price), xytext=(30, 10), textcoords='offset points',
            fontsize=9, fontweight='bold', color=ACCENT,
            arrowprops=dict(arrowstyle='->', color=ACCENT, lw=1.2))
ax.annotate(f'Max Drawdown Trough\n{max_dd_date.strftime("%b %Y")}',
            xy=(max_dd_date, df['Close'].iloc[max_dd_idx]), xytext=(30, -20), textcoords='offset points',
            fontsize=9, color=ACCENT,
            arrowprops=dict(arrowstyle='->', color=ACCENT, lw=1.2))
chart_price_trend = fig_to_base64(fig)

# ── Chart 2: Price with Drawdown Overlay ──────────────────────────────────
fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(14, 8), height_ratios=[2, 1], sharex=True)
ax1.plot(df['Date'], df['Close'], color=PRIMARY, linewidth=0.7)
ax1.set_ylabel('Closing Price (USD)')
ax1.set_title('AXP Price & Drawdown', fontweight='bold')
ax1.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}'))
ax2.fill_between(df['Date'], df['Drawdown'] * 100, 0, color=ACCENT, alpha=0.4)
ax2.plot(df['Date'], df['Drawdown'] * 100, color=ACCENT, linewidth=0.5)
ax2.set_ylabel('Drawdown (%)')
ax2.set_ylim(min(df['Drawdown'] * 100) * 1.1, 5)
for ep in dd_episodes[:5]:
    ax2.annotate(f'{ep["drawdown"]:.1f}%',
                 xy=(ep['trough_date'], ep['drawdown']),
                 fontsize=8, fontweight='bold', color='darkred', ha='center', va='top')
chart_drawdown = fig_to_base64(fig)

# ── Chart 3: Annualized Rolling Volatility ────────────────────────────────
